<script>
const sudokuSize = 9;
const emptyCell = '.';
let cells = [];
let selectedCell = null;

function generateSudoku() {
  let grid = Array.from({ length: sudokuSize }, () => Array(sudokuSize).fill(emptyCell));
  const values = '123456789';
  for (let i = 0; i < 15; i++) {
    const row = Math.floor(Math.random() * sudokuSize);
    const col = Math.floor(Math.random() * sudokuSize);
    const value = values[Math.floor(Math.random() * 9)];
    grid[row][col] = value;
  }
  for (let i = 0; i < sudokuSize; i++) {
    for (let j = 0; j < sudokuSize; j++) {
      if (grid[i][j] === emptyCell) {
        const values = '123456789';
        let canPlace = false;
        while (!canPlace) {
          const value = values[Math.floor(Math.random() * 9)];
          if (isValid(grid, i, j, value)) {
            grid[i][j] = value;
            canPlace = true;
          }
        }
      }
    }
  }
  return grid;
}

function isValid(grid, row, col, value) {
  for (let i = 0; i < sudokuSize; i++) {
    if (grid[row][i] === value) return false;
    if (grid[i][col] === value) return false;
  }
  const startRow = row - row % 3;
  const startCol = col - col % 3;
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      if (grid[startRow + i][startCol + j] === value) return false;
    }
  }
  return true;
}

function renderSudoku(grid) {
  const sudokuDiv = document.getElementById('sudoku');
  cells.forEach(cell => cell.remove());
  cells = [];
  for (let i = 0; i < sudokuSize; i++) {
    for (let j = 0; j < sudokuSize; j++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.textContent = grid[i][j];
      if (grid[i][j] !== emptyCell) cell.classList.add('selected');
      cell.addEventListener('click', () => selectCell(i, j));
      cell.addEventListener('keydown', (e) => e.key === 'Backspace' ? selectCell(i, j) : insertValue(i, j, e.key));
      sudokuDiv.appendChild(cell);
      cells.push(cell);
    }
  }
}

function selectCell(row, col) {
  if (cells[row * sudokuSize + col].textContent === emptyCell) {
    cells.forEach(cell => cell.classList.remove('selected'));
    cells[row * sudokuSize + col].classList.add('selected');
    selectedCell = cells[row * sudokuSize + col];
  }
}

function insertValue(row, col, value) {
  if (selectedCell.textContent === emptyCell) {
    selectedCell.textContent = value;
    if (!isValid(grid, row, col, value)) {
      selectedCell.textContent = emptyCell;
      selectedCell.classList.add('error');
      setTimeout(() => selectedCell.classList.remove('error'), 1000);
    }
  }
}

function newGame() {
  const grid = generateSudoku();
  renderSudoku(grid);
  selectedCell = null;
}

const grid = generateSudoku();
renderSudoku(grid);
</script>
</body>
</html>
